const name=(g,t)=>g.builtin?t('clubRoom_'+g.category):g.name;
const empty=t=>`<p class="empty">${t('noItems')}</p>`;
const attrs=(h,g,extra='')=>`data-group="${h(g.id)}" ${extra}`;
export function clubChatPage({state,selected,t,h,btn,displayDate}){
  const chat=state.clubChat;if(!chat)return `<section class="card stack"><p>${t('clubChatContext')}</p>${btn(t('identitySwitchLabel'),'nav','data-id="identity"','primary')}</section>`;
  const g=chat.groups.find(g=>g.id===selected)||chat.groups[0];
  return `<div class="stack"><section class="card stack"><h2>${t('clubChatTitle')} · ${h(state.identity.club.name)}</h2><p>${t('clubChatNotice')}</p>${chat.incoming.map(v=>`<div class="rule row wrap"><div class="grow"><b>${h(name(v.group,t))}</b><br><small>${h(v.senderName||'')} · ${t('coachingIncoming')}</small></div>${btn(t('accept'),'clubChatResponse',`data-id="${h(v.id)}" data-accept="true"`,'primary')}${btn(t('decline'),'clubChatResponse',`data-id="${h(v.id)}" data-accept="false"`,'secondary')}</div>`).join('')}</section><div class="chat-layout"><div class="card chat-list">${chat.groups.map(r=>`<button class="${g?.id===r.id?'active':''}" data-action="clubChatOpen" data-id="${h(r.id)}" aria-current="${g?.id===r.id?'true':'false'}"><b>${h(name(r,t))}</b><br><small>${t('clubRoom_'+r.category)}${r.archived?' · '+t('coachingArchived'):''}</small></button>`).join('')||empty(t)}</div><div class="card stack">${g?`<div class="row space wrap"><h3>${h(name(g,t))}</h3>${!g.builtin?btn(t('clubChatLeave'),'clubChatLeave',attrs(h,g),'secondary'):''}</div><div class="messages rule">${g.messages.map(m=>`<article class="bubble ${m.owner===state.me.id?'mine':''}"><small>${h(m.senderName||t('notAvailable'))}</small><p class="post-text">${h(m.text)}</p><small>${h(displayDate(m.at))}</small><div class="row wrap chat-message-actions">${m.owner!==state.me.id?btn(t('report'),'clubChatReport',attrs(h,g,`data-id="${h(m.id)}"`),'chip')+btn(t('block'),'clubChatBlock',`data-id="${h(m.owner)}"`,'chip'):''}${(m.owner===state.me.id||g.canRemove)?btn(t('remove'),'clubChatRemove',attrs(h,g,`data-id="${h(m.id)}"`),'chip'):''}</div></article>`).join('')||empty(t)}</div>${!g.archived?`<form class="chat-form" data-form="clubChatMessage"><input type="hidden" name="groupId" value="${h(g.id)}"><input name="text" placeholder="${t('message')}" aria-label="${t('message')}" required maxlength="1000" autocomplete="off"><button type="submit" class="primary">${t('send')}</button></form>`:`<p class="notice">${t('clubChatArchived')}</p>`}`:empty(t)}</div></div>${chat.manage?clubChatManagement({chat,t,h,btn}):''}</div>`;
}
function clubChatManagement({chat,t,h,btn}){
  return `<section class="card stack"><h2>${t('clubChatManage')}</h2><p>${t('clubChatManageNotice')}</p><form class="stack" data-form="clubChatCreate"><label>${t('groupName')}<input name="name" required maxlength="80"></label><label>${t('clubChatCategory')}<select name="category">${['club','staff','coach','finance'].map(c=>`<option value="${c}">${t('clubRoom_'+c)}</option>`).join('')}</select></label><button class="primary" type="submit">${t('clubChatCreate')}</button></form>${chat.management.map(g=>`<article class="rule stack"><div class="row space wrap"><h3>${h(name(g,t))}</h3><span class="badge gold">${t('clubRoom_'+g.category)}${g.archived?' · '+t('coachingArchived'):''}</span></div>${g.members.map(m=>`<div class="row space wrap"><span>${h(m.name||t('notAvailable'))}</span>${!g.archived?btn(t('clubChatRemoveMember'),'clubChatMemberRemove',attrs(h,g,`data-id="${h(m.id)}"`),'secondary'):''}</div>`).join('')||empty(t)}${g.pending.map(v=>`<div class="row space wrap"><small>${h(v.name||t('notAvailable'))} · ${t('coachingPending')}</small>${btn(t('coachingCancel'),'clubChatCancelInvite',attrs(h,g,`data-id="${h(v.id)}"`),'secondary')}</div>`).join('')}${!g.archived?`<form class="stack" data-form="clubChatInvite"><input type="hidden" name="groupId" value="${h(g.id)}"><label>${t('clubChatInvite')}<select name="target" required><option value="">${t('choosePeople')}</option>${g.candidates.map(p=>`<option value="${h(p.id)}">${h(p.name||t('notAvailable'))}</option>`).join('')}</select></label><button class="secondary" type="submit">${t('invite')}</button></form>${btn(t('clubArchive'),'clubChatArchive',attrs(h,g),'danger')}`:''}</article>`).join('')||empty(t)}</section>`;
}
